const SCREENS=[];
SCREENS[0]=()=>`${head(APP.headline,APP.sub,button('Content library','changeView(2)','','folder')+button('Document studio','proposalStudio()','primary','file'))}<div class="chat-shell"><aside class="chat-history">${button('New conversation','newProposal()','','plus')}<span class="upper">RECENT PROPOSALS</span>${APP.rows.map((r,i)=>`<div class="historyitem ${state.selected===i?'active':''}" role="button" tabindex="0" onclick="selectProposal(${i})" onkeydown="if(event.key==='Enter')selectProposal(${i})">${esc(r[0])}<small>${esc(r[1])} · ${esc(r[2])}</small></div>`).join('')}<div class="divider"></div><span class="upper">APPROVED CONTEXT</span>${APP.library.map((r,i)=>button(esc(r[0]),'openSource()','quiet','file')).join('')}</aside><section class="chat-main"><div class="minilabel"><span>PROPOSAL COPILOT</span>${tag('Draft in progress','blue')}</div><h2>${esc(APP.rows[state.selected][0])}</h2><div class="chat-log"><div class="chat-message user">${avatar('AM')}<div><b>Alex Morgan</b>Help us respond to this RFP. We need a practical 90-day plan, a clear budget, and a handoff our operations team can own.<div class="attachment" style="margin:13px 0 0">${icon('file')}<div><b>northstar-operations-rfp.pdf</b><div class="tiny">Sample document · 18 pages</div></div></div></div></div><div class="chat-message">${avatar('AI')}<div><b>Proposal copilot</b>I have organized the response into five sections: the business objective, delivery approach, implementation plan, investment, and acceptance criteria.<br><br>The RFP asks for a 90-day pilot. I recommend three phases with a review at each handoff. Before drafting the final timeline, please confirm who approves source access and which workflow should launch first.<div class="actions" style="margin-top:16px">${button('Review requirements','proposalRequirements()','','check')}${button('Open first draft','proposalStudio()','','file')}</div></div></div>${state.messages.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}">${avatar(m.role==='user'?'AM':'AI')}<div><b>${m.role==='user'?'Alex Morgan':'Proposal copilot'}</b>${esc(m.text)}</div></div>`).join('')}</div><div class="chat-compose"><textarea id="chat-input" aria-label="Proposal message" placeholder="Ask a question, refine a section, or add context…"></textarea><div>${button('Attach RFP','attachRfp()','quiet','plus')}<small>Sample workspace · AI simulation</small>${button('Send','sendProposal()','primary','send')}</div></div></section><aside class="chat-context"><h3>Opportunity brief</h3>${[['Client',APP.rows[state.selected][1]],['Delivery window','90-day pilot'],['Investment ceiling','$75,000'],['Decision owner','Operations leadership']].map(([a,b])=>`<div class="contextitem"><span>${a}</span><b>${b}</b></div>`).join('')}<div style="margin-top:23px"><div class="minilabel"><span>REQUIREMENT COVERAGE</span><b>7 / 10</b></div>${progress(70)}${checklist(['Business objective captured','Delivery phases drafted','Source access owner needed'])}</div>${aiCard('Before submission','Confirm the data access owner and acceptance criteria before committing to the implementation dates.')}</aside></div>`;
function sendProposal(){const q=document.getElementById('chat-input').value.trim();if(!q)return;state.messages.push({role:'user',text:q},{role:'ai',text:/budget|cost/i.test(q)?'For the sample $75,000 ceiling, separate discovery, implementation, and adoption support. The draft should include assumptions and running costs; confirm actual pricing with the delivery owner.':/timeline|phase/i.test(q)?'Use discovery and access planning first, then a working pilot, followed by testing and adoption. Keep each phase conditional on agreed source access and acceptance checks.':APP.ai});render()}
function selectProposal(i){state.selected=i;state.messages=[];render()}
function newProposal(){state.messages=[];toast('A fresh conversation is ready. Add the new opportunity context.');render()}
function attachRfp(){modal('RFP intake',`<div class="attachment">${icon('file')}<div><b>northstar-operations-rfp.pdf</b><div class="tiny">Included sample RFP context</div></div></div><p>This demonstration uses the prepared sample brief. A production intake would accept your file, extract requirements, and preserve the source references.</p><div class="actions">${button('Use sample RFP','closeModal();proposalRequirements()','primary')}</div>`)}
function proposalRequirements(){modal('Requirements & open questions',checklist(['90-day pilot and phased delivery plan','Operations workflow selected for the first release','Named owner for each review','Acceptance criteria and test evidence','Client confirmation required: source access owner','Client confirmation required: recurring operating cost'])+`<div class="actions">${button('Open document studio','proposalStudio()','primary','file')}</div>`)}
function proposalStudio(){modal('Proposal document studio',`<div class="split-editor"><section><div class="minilabel"><b>EDIT THE RESPONSE</b>${tag('Working draft','blue')}</div><textarea id="proposal-draft" style="min-height:440px" oninput="state.proposalDraft=this.value">${esc(state.proposalDraft||'Executive summary\n\nNorthstar is seeking a practical way to connect operating information and reduce manual handoffs. We propose a focused 90-day pilot around one agreed workflow.\n\nDelivery approach\n\nPhase 1: Map the work, confirm the baseline, and secure approved source access.\nPhase 2: Build and review a working application with representative users.\nPhase 3: Test complete journeys, onboard a small group, and review outcomes.\n\nAcceptance\n\nAgree on source accuracy, review controls, user completion, and the handoff before release.')}</textarea><div class="actions" style="margin-top:15px">${button('Save draft','saveProposal()','primary','check')}${button('Review requirements','proposalRequirements()','','file')}</div></section><article class="document"><span class="upper">NORTHSTAR / PROPOSAL</span><h1>Operations intelligence pilot</h1><p>Prepared for the operations leadership team</p><div class="divider"></div><h3>01 / Executive summary</h3><p>A focused implementation built around the information, decisions, and handoffs that matter to your team.</p><h3>02 / Delivery plan</h3>${checklist(['Discovery & workflow design','Working application & review','Testing, adoption & handoff'])}<h3>03 / Review before submission</h3><p>Confirm source access, acceptance criteria, investment assumptions, and the approval owner.</p></article></div>`,true)}
function saveProposal(){state.proposalDraft=document.getElementById('proposal-draft').value;toast('Proposal draft saved in this demo session.')}
const attendeeNames=['Morgan Reed','Alex Chen','Taylor Brooks','Jordan Ellis'];
function responseText(){const name=attendeeNames[state.selected].split(' ')[0];return state.reply||`Hi ${name},\n\nThank you for joining our session on making AI useful in everyday operations. Your question about connecting existing systems stood out.\n\nThe practical starting point is one workflow: identify what comes in, which decisions need context, and where people review the result. I thought the operations brief would be useful for your team.\n\nIf this is something you are working through, I would welcome a short conversation about the process you would tackle first.\n\nAlex`}
SCREENS[1]=()=>`${head(APP.headline,APP.sub,button('Campaign brief','campaignBrief()','','file')+button(state.approved?'Draft approved':'Approve draft','approveDraft()','primary','check'))}<div class="maildesk"><aside class="panel"><div class="panelhead"><div><h2>Webinar audience</h2><p>Operations intelligence · 4 sample contacts</p></div></div><div class="list">${APP.rows.map((r,i)=>`<button class="mailitem ${state.selected===i?'active':''}" onclick="selectAttendee(${i})"><b>${esc(r[0])}</b>${esc(r[1])}<p>${esc(r[2])} · ${esc(r[3])}</p><small>${i===state.selected&&state.approved?'Approved locally':esc(r[4])}</small></button>`).join('')}</div><div class="panelbody"><span class="upper">CAMPAIGN PROGRESS</span>${bar('Drafts prepared',100,'4 / 4')}${bar('Reviewed',state.approved?25:0,state.approved?'1 / 4':'0 / 4')}<p class="note">Sample review state. No email is sent.</p></div></aside><section class="panel editor"><div class="editorlabel">PERSONALIZED FOLLOW-UP / DAY ${[0,3,7,14][state.version]}</div><div class="tabs">${['Email','Follow-up 1','Follow-up 2','Follow-up 3'].map((x,i)=>button(x,`selectCadence(${i})`,state.version===i?'active':'')).join('')}</div><h2>${['A practical next step after the webinar','A workflow example for your team','Three questions to shape the pilot','Worth a short conversation?'][state.version]}</h2><div class="posthead">${avatar(attendeeNames[state.selected].split(' ').map(x=>x[0]).join(''))}<div><b>To ${attendeeNames[state.selected]}</b><small>${APP.rows[state.selected][1]} · No live address</small></div><span class="draft-status">${state.approved?'Approved':'Working draft'}</span></div><div class="subject"><span class="muted">Subject</span><input aria-label="Email subject" value="${['Your question about connected workflows','A practical operations example','A short checklist for your first AI workflow','Should we compare notes?'][state.version]}"></div><textarea class="emailbody" id="reply" aria-label="Email draft" oninput="state.reply=this.value;state.approved=false">${esc(responseText())}</textarea><div class="attachment">${icon('file')}<div><b>Operations intelligence brief</b><div class="tiny">Approved sample content</div></div>${button('Inspect','openSource()','quiet','arrow')}</div><div class="actions">${button('Make it shorter','shortenReply()','','spark')}${button('Refine with AI','openAI()','','spark')}${button('Save draft','saveDraft()','primary','check')}</div><div class="cadence">${APP.library.map((r,i)=>button(`<b>${r[0]}</b><small>${r[1]} · ${r[3]}</small>`,`selectCadence(${i})`)).join('')}</div></section><div class="stack">${aiCard('Why this message fits','The selected contact asked about existing systems. The draft connects that question to a concrete workflow and approved follow-up content.')}${panel('Grounded in the session',checklist(['Transcript section: workflow integration','Audience signal: question submitted','Relevant content: operations brief'])+`<div class="divider"></div><p class="note">The source, audience context, and suggested timing are illustrative.</p>`)}${panel('Review checklist',checklist(['Personal context is accurate','Approved resources are relevant','Tone and next step are appropriate']))}</div></div>`;
function selectAttendee(i){state.selected=i;state.reply='';state.approved=false;render()}
function selectCadence(i){state.version=i;state.reply=i?`Hi ${attendeeNames[state.selected].split(' ')[0]},\n\n${['','I wanted to share a practical example of how a focused workflow can connect the information your team already uses.','Three useful questions: which task repeats, what context is missing, and who should review the result?','Would comparing notes on one workflow be useful? If the timing is not right, no problem.'][i]}\n\n${i===1?'The approved operations brief gives a starting structure for the discussion.':i===2?'Those answers give the team a clear starting point for a pilot.':'We can focus the conversation on the work that matters most to your team.'}\n\nAlex`:'';state.approved=false;render()}
function shortenReply(){state.reply=`Hi ${attendeeNames[state.selected].split(' ')[0]},\n\nThanks for joining the webinar. Your question about connecting existing systems is a useful place to start.\n\nI have included the approved operations brief. Would a short conversation about one workflow be helpful?\n\nAlex`;state.approved=false;render()}
function approveDraft(){state.approved=true;render();toast('Draft approved locally. No email was sent.')}
function saveDraft(){state.reply=document.getElementById('reply')?.value||state.reply;toast('Draft saved in this sample session.')}
function campaignBrief(){modal('Webinar source brief',`<p><b>Session:</b> Making AI useful in everyday operations</p><div class="divider"></div>${checklist(['Start with a specific business workflow','Connect approved information and existing systems','Keep review and approval explicit','Measure adoption and operating outcomes'])}<div class="actions">${button('Inspect approved content','openSource()','primary','file')}</div>`)}
SCREENS[2]=()=>`${head()}${metrics([['Priority leads','4','Fictional accounts',true],['High fit + intent','2','Ready for owner review'],['Need more context','1','Research before outreach',true],['Assigned owners','3 / 4','One lead needs routing',true]])}<div class="layout"><div class="panel"><div class="panelhead"><div><h2>Lead priority queue</h2><p>Review the evidence behind each recommendation.</p></div><div class="filterchips">${['All','High priority','Unassigned'].map(f=>button(f,`setLeadFilter('${f}')`,state.filter===f?'active':'')).join('')}</div></div>${table(['Account / contact','Fit','Intent','Priority','Owner'],APP.rows.map((r,i)=>({r,i})).filter(({r})=>state.filter==='All'||state.filter==='High priority'&&Number(r[2])>=85||state.filter==='Unassigned'&&r[4]==='Unassigned').map(({r,i})=>[`${r[0]}<small>${r[1]}</small>`,r[2],r[3],tag(i<2?'High priority':'Review',i<2?'':'amber'),r[4]]))}<div class="panelbody"><p class="note">Priority is an illustrative combination of fit and intent. It is not a probability of conversion.</p></div></div><aside class="stack">${panel('Northstar Manufacturing',`<div class="score-ring" style="--score:90"><div><b>90</b><small>PRIORITY SCORE</small></div></div>${bar('Company fit',92)}${bar('Engagement intent',88)}<div class="divider"></div><p class="small muted">Clear operating need, relevant company profile, and repeated engagement around integration.</p><div class="actions" style="margin-top:17px">${button('Inspect lead','openRecord(0)','primary','arrow')}</div>`)}${aiCard('Recommended next move')}</aside></div>`;
function setLeadFilter(v){state.filter=v;render()}
SCREENS[3]=()=>`${head(APP.headline,APP.sub,button('Run simulation','runSimulation()','primary','spark'))}<div class="layout"><div class="stack">${panel('Message under test',`<div class="toolbar"><div class="tabs">${['Variant A','Variant B','Variant C'].map((v,i)=>button(v,`setVariant(${i})`,state.simVariant===i?'active':'')).join('')}</div>${tag(state.simRun?'Evaluation complete':'Ready to simulate',state.simRun?'':'blue')}</div><textarea id="sim-message" rows="5" aria-label="Message to test" oninput="state.simMessage=this.value;state.simRun=false">${esc(state.simMessage||['Bring AI into the work your team already does. Start with one workflow, connect the right information, and build a useful application around it.','A focused 90-day pilot: one business workflow, a named owner, a clear baseline, and a working application your team can review.','Less manual coordination. Clearer decisions. A purpose-built AI workspace that connects your team to the information it needs.'][state.simVariant])}</textarea><p class="note" style="margin-top:10px">Synthetic persona feedback is directional and should be validated with real users.</p>`)}<div class="grid2">${[['DF','Dana Foster','COO','Operational clarity',74],['SR','Sam Rivera','IT director','Integration & access',68],['RP','Riley Park','Finance leader','Cost & evidence',65],['CS','Casey Stone','End user','Practical usability',81]].map(([a,n,r,l,v],i)=>`<article class="persona"><div class="persona-top">${avatar(a)}<div><h3>${n}</h3><span class="role">${r} · Synthetic persona</span></div></div><span class="upper">${l}</span><div class="score">${state.simRun?Math.min(95,v+state.simVariant*5):'—'}<small> / 100</small></div>${progress(state.simRun?v+state.simVariant*5:0)}<blockquote>${state.simRun?['Show me the specific workflow and the review points.','Explain the source access and integration boundaries.','Make the baseline, operating costs, and benefit assumptions visible.','Show me what I do in the application on day one.'][i]:'Run the simulation to inspect this persona’s reaction.'}</blockquote>${button('Inspect feedback',`personaFeedback(${i})`,'quiet','arrow')}</article>`).join('')}</div></div><aside class="stack">${panel('Experiment setup',`<div class="field"><label>Audience</label><select aria-label="Simulation audience"><option>Enterprise buying group</option><option>Internal operations team</option></select></div><div class="field"><label>Evaluation goal</label><select aria-label="Simulation goal"><option>Clarity & readiness to engage</option><option>Workflow relevance</option></select></div>${checklist(['Operational perspective','Technology perspective','Financial perspective','User perspective'])}<div class="divider"></div><p class="note">4 synthetic personas · 3 message variants · Scores illustrate the feedback workflow.</p>`)}${aiCard('Refinement direction','Make the first workflow, review controls, and measurable pilot outcome explicit. Test the revision with real stakeholders.')}</aside></div>`;
function runSimulation(){state.simMessage=document.getElementById('sim-message')?.value||state.simMessage;state.simRun=true;render();toast('Illustrative persona evaluation complete.')}
function setVariant(i){state.simVariant=i;state.simMessage='';state.simRun=false;render()}
function personaFeedback(i){modal(['Operations feedback','IT feedback','Finance feedback','End-user feedback'][i],`<p>${esc(APP.ai)}</p><div class="divider"></div><h3>Suggested test</h3><p style="margin-top:12px">Ask a real stakeholder to explain the proposed workflow back to you, identify what information is missing, and describe the next decision they would need to make.</p><div class="actions">${button('Refine the message','closeModal()','primary')}</div>`)}
SCREENS[4]=()=>{const total=state.budget.reduce((a,b)=>a+b,0);return `${head(APP.headline,APP.sub,button('Discuss the plan','openAI()','','spark')+button(state.approved?'Submitted for review':'Submit for review','approveBudget()','primary','check'))}${metrics([['Annual plan',money(total),'Sum of editable line items',true],['Monthly run rate',money(total/12),'Annual plan ÷ 12',true],['Planning baseline','$426,000','Illustrative comparison',true],['Variance',money(total-426000),(total>=426000?'Above':'Below')+' baseline',true]])}<div class="layout"><div class="stack"><section class="panel"><div class="panelhead"><div><h2>Operations department budget</h2><p>Adjust the annual amounts to model a new plan.</p></div>${tag(state.approved?'Submitted locally':'Working draft',state.approved?'':'blue')}</div><div class="tablewrap"><table class="sheet"><thead><tr><th>ACCOUNT</th><th>BASELINE</th><th>FY2027 PLAN</th><th>VARIANCE</th></tr></thead><tbody>${['Staffing','Contractor support','Software & tools','Training & adoption','Travel','Contingency'].map((n,i)=>`<tr><td>${n}</td><td>${money([180000,72000,48000,54000,36000,36000][i])}</td><td><input type="number" min="0" step="1000" aria-label="${n} annual budget" value="${state.budget[i]}" onchange="changeBudget(${i},this.value)"></td><td>${money(state.budget[i]-[180000,72000,48000,54000,36000,36000][i])}</td></tr>`).join('')}</tbody><tfoot><tr><td>Total annual plan</td><td>$426,000</td><td>${money(total)}</td><td>${money(total-426000)}</td></tr></tfoot></table></div></section>${panel('Budget discussion',`<div class="chat-message">${avatar('AI')}<div><b>Budget copilot</b>The plan keeps recurring operating commitments visible. Staffing represents ${total?Math.round(state.budget[0]/total*100):0}% of the current budget. Review contract renewals before reducing the software line.</div></div><div class="chat-compose"><textarea id="budget-question" aria-label="Budget question" placeholder="Ask about a reduction, an assumption, or a cost driver…"></textarea><div><small>Sample planning assistance</small>${button('Discuss','budgetDiscuss()','primary','spark')}</div></div>`)}<p class="note">Amounts are illustrative planning inputs. No finance system is connected.</p></div><aside class="stack">${panel('Plan distribution',state.budget.map((v,i)=>bar(['Staffing','Contractors','Software','Training','Travel','Reserve'][i],total?v/total*100:0,money(v))).join(''))}${aiCard('Review before submission','Confirm recurring commitments, owner assumptions, and the contingency basis. A budget reduction should identify what work changes, not simply reduce every line by the same percentage.')}</aside></div>`}
function changeBudget(i,v){state.budget[i]=Math.max(0,Number(v)||0);state.approved=false;render()}
function approveBudget(){state.approved=true;render();toast('Budget marked submitted for local review. No finance system updated.')}
function budgetDiscuss(){const q=document.getElementById('budget-question').value.trim();if(!q)return;state.aiMessages=[{q,a:APP.ai}];drawAI()}
SCREENS[5]=()=>`${head(APP.headline,APP.sub,`<select data-browse aria-label="Sales period" onchange="state.salesPeriod=this.value;render()"><option ${state.salesPeriod!=='Q3'?'selected':''}>Q4</option><option ${state.salesPeriod==='Q3'?'selected':''}>Q3</option></select>${button('AI revenue briefing','openAI()','primary','spark')}`)}${metrics([['Closed revenue',state.salesPeriod==='Q3'?'$884,000':'$962,000','Sample period total',true],['Open pipeline','$588,000','4 sample opportunities',true],['Weighted forecast','$325,200','Illustrative stage weights',true],['Win rate','32%','8 of 25 sample decisions',true]])}<div class="two-thirds"><div class="stack">${panel('Quarterly revenue',salesHistory(),'Monthly closes · same-month comparison, prior year',button('Inspect period','salesPeriod()','quiet','arrow'))}<section class="panel"><div class="panelhead"><div><h2>Opportunities that shape the quarter</h2><p>Open a record to inspect its context.</p></div>${button('View pipeline','changeView(1)','quiet','arrow')}</div>${table(APP.cols,APP.rows)}</section></div><aside class="stack">${panel('Pipeline by stage',bar('Qualification',12,'$72k')+bar('Discovery',16,'$96k')+bar('Proposal',31,'$180k')+bar('Negotiation',41,'$240k'))}${aiCard('Executive perspective')}${panel('Upcoming decisions',`<div class="activity"><span class="dot"></span><div><p>Cedar scope and approval review</p><small>Jordan Ellis · Nov 06</small></div></div><div class="activity"><span class="dot"></span><div><p>Northstar source access confirmation</p><small>Alex Morgan · Nov 09</small></div></div>`)}</aside></div>`;
function salesPeriod(){modal('Revenue period detail',`<p>${state.salesPeriod==='Q3'?'Q3 sample closed revenue: $884,000.':'Q4 sample closed revenue: $962,000.'} The open pipeline contains four fictional opportunities totaling $588,000. The weighted forecast of $325,200 uses stage weights of 20%, 30%, 50%, and 80% in the sample model.</p><div class="actions">${button('Inspect opportunities','closeModal();changeView(1)','primary')}</div>`)}
SCREENS[6]=()=>{const people=[['AM','Alex Morgan','Solution design',32],['TK','Taylor Kim','Integration',28],['JE','Jordan Ellis','Application build',44],['CS','Casey Stone','Testing & adoption',24]];return `${head(APP.headline,APP.sub,button('AI rebalance suggestion','rebalance()','','spark')+button('New assignment','newRecord()','primary','plus'))}${metrics([['Team capacity',state.capacity*4+' hrs','4 people × '+state.capacity+' hours',true],['Planned delivery','128 hrs','Sample assignment total',true],['Utilization',Math.round(128/(state.capacity*4)*100)+'%','Planned hours ÷ capacity',true],['Overallocated',people.filter(p=>p[3]>state.capacity).length,'Review before committing',true]])}<div class="panel"><div class="panelhead"><div><h2>Weekly team planner</h2><p>November 2–6 · Click an allocation to inspect it.</p></div><div class="actions"><label class="tiny muted" for="capacity">Hours / person</label><input id="capacity" aria-label="Weekly capacity per person" type="number" min="1" max="80" value="${state.capacity}" onchange="setInput('capacity',this.value)" style="width:70px"></div></div><div class="tablewrap"><div class="weekgrid">${['Team member','Mon 02','Tue 03','Wed 04','Thu 05','Fri 06'].map(x=>`<div class="weekhead">${x}</div>`).join('')}${people.map(([a,n,r,h],i)=>`<div class="person">${avatar(a)}<div>${n}<small>${r} · ${Math.round(h/state.capacity*100)}%</small></div></div>${Array.from({length:5},(_,d)=>`<div><div class="allocation ${i===2&&d>2?'amber':d===4?'gray':''}" role="button" tabindex="0" onclick="allocationDetail(${i},${d})" onkeydown="if(event.key==='Enter')allocationDetail(${i},${d})">${['Northstar · Design','Harbor · Integration','Cedar · Build','Northstar · Testing'][i]}<br>${(h/5).toFixed(1)} hrs${i===2&&d===3?' · Review capacity':''}</div>${d===2?'<span class="tiny muted">Team review · 1 hr</span>':''}</div>`).join('')}`).join('')}</div></div></div><div class="grid2" style="margin-top:22px">${aiCard('Capacity recommendation')}${panel('Availability & decisions',checklist(['Confirm planned leave and non-project commitments','Check skills before reallocating an assignment','Have the delivery owner approve schedule changes']))}</div>`}
function allocationDetail(i,d){modal('Assignment detail',`<div class="grid2"><div class="field"><label>Team member</label><input value="${['Alex Morgan','Taylor Kim','Jordan Ellis','Casey Stone'][i]}"></div><div class="field"><label>Planned hours</label><input type="number" min="0" max="16" value="${[6,6,9,5][i]}"></div></div><p>Sample assignment on ${['Monday','Tuesday','Wednesday','Thursday','Friday'][d]}. This record should be reviewed against availability and delivery priorities.</p><div class="actions">${button('Save review note','closeModal();toast(\'Assignment review saved in this demo.\')','primary')}</div>`)}
