function comparisonPlot(labels, series, unit) {
  const ceiling = Math.max(...series.flatMap(s => s.values));
  return `<figure class="compare-plot"><figcaption>${series.map((s,i)=>`<span><i class="series-${i}"></i>${esc(s.label)}</span>`).join('')}</figcaption>
    ${labels.map((label,j)=>`<div class="plot-group"><strong>${esc(label)}</strong><div>${series.map((s,i)=>`<div class="plot-track" aria-label="${esc(s.label)}: ${esc(unit(s.values[j]))}"><i class="series-${i}" style="width:${s.values[j]/ceiling*100}%"></i><b>${esc(unit(s.values[j]))}</b></div>`).join('')}</div></div>`).join('')}</figure>`;
}
const thousands = value => '$'+value+'k';
