SCREENS[9]=()=>{const base=3840000,forecast=base*(1+state.growth/100);return `${head(APP.headline,APP.sub,button('Compare scenarios','forecastCompare()','','chart')+button('Save scenario','primaryAction()','primary','check'))}${metrics([['Baseline revenue','$3.84M','Sample annual run rate',true],['Scenario revenue',money(forecast),'Growth assumption applied',true],['Change from baseline',money(forecast-base),state.growth+'% growth input',true],['Scenario status','Working','No forecast is guaranteed',true]])}<div class="scenario-grid"><div class="stack">${panel('Baseline versus working scenario',`<div class="legend"><span><i></i>Working scenario</span><span><i></i>Baseline</span></div>${chart([28,34,32,43,45,52,57,63,65,74,80,88].map((v,i)=>v+state.growth*i/32))}`,'Illustrative monthly shape · Annual total calculated from growth')}<section class="panel"><div class="panelhead"><h2>Scenario comparison</h2></div>${table(['Scenario','Growth input','Annual revenue','Change'],[['Baseline','0%','$3,840,000','—'],['Downside','−8%','$3,532,800','−$307,200'],['Working scenario',state.growth+'%',money(forecast),money(forecast-base)]],false)}</section>${aiCard('Interpret the scenario')}</div><aside class="panel scenario-controls"><span class="eyebrow">WORKING ASSUMPTIONS</span><h3 style="margin-top:10px">Change the growth driver.</h3>${slider('Annual revenue growth','growth',state.growth,-40,60)}<div class="divider"></div><div class="field"><label for="baseline-revenue">Baseline annual revenue</label><input id="baseline-revenue" aria-label="Baseline annual revenue" value="$3,840,000" readonly></div><p class="note">The sample baseline is fixed at $3.84M. Growth is applied directly to that amount. Production forecasting would use approved drivers and data.</p><div class="divider"></div><div class="scenario-note">Changing a scenario is a planning exercise. Validate capacity, pipeline evidence, and costs before committing to the plan.</div></aside></div>`}
function forecastCompare(){modal('Scenario comparison',`<p>Baseline: ${money(3840000)}. Working scenario: ${money(3840000*(1+state.growth/100))}. The difference is ${money(3840000*state.growth/100)} at the current ${state.growth}% growth input.</p><div class="divider"></div><p>Review the operating evidence behind the growth assumption and compare the downside before accepting the forecast.</p><div class="actions">${button('Back to scenario','closeModal()','primary')}</div>`)}
function roiValues(){const gross=state.hours*52*state.rate*(state.reduction/100)*(state.adoption/100)*(state.realization/100),net=gross-state.running;return {gross,net,roi:state.build?((net-state.build)/state.build)*100:null,payback:net>0?state.build/(net/12):null,hours:state.hours*52*(state.reduction/100)*(state.adoption/100)*(state.realization/100)}}
SCREENS[10]=()=>{const v=roiValues();return `${head(APP.headline,APP.sub,button('Inspect calculation','roiMethod()','','file')+button('Save evaluation','primaryAction()','primary','check'))}<div class="scenario-grid roi-grid"><aside class="panel scenario-controls"><span class="eyebrow">PROJECT INPUTS</span><h3 style="margin-top:10px">Support response assistant</h3><div class="grid2" style="gap:12px">${field('Hours spent / week','hours',state.hours,'number',0,10000)}${field('Loaded hourly rate ($)','rate',state.rate,'number',0,10000)}</div>${slider('Potential effort reduction','reduction',state.reduction)}${slider('User adoption','adoption',state.adoption)}${slider('Benefit realization','realization',state.realization)}<div class="grid2" style="gap:12px">${field('One-time build ($)','build',state.build,'number',0,10000000)}${field('Annual running cost ($)','running',state.running,'number',0,10000000)}</div><p class="note">Inputs are unvalidated sample assumptions. Time released is potential capacity, not automatically cash savings.</p></aside><section class="stack"><div class="bigresult"><span class="upper">MODELED ANNUAL BENEFIT / AFTER RUNNING COST</span><div class="balance">${money(v.net)}</div><p>Potential gross value ${money(v.gross)} less ${money(state.running)} annual operating cost.</p><div class="kpi-row"><div><span>FIRST-YEAR ROI</span><b>${v.roi===null?'—':v.roi.toFixed(0)+'%'}</b></div><div><span>PAYBACK</span><b>${v.payback===null?'Not reached':v.payback.toFixed(1)+' months'}</b></div><div><span>CAPACITY RELEASED</span><b>${v.hours.toFixed(0)} hrs / year</b></div></div></div>${panel('What makes the economics work',bar('Potential reduction',state.reduction)+bar('Expected adoption',state.adoption)+bar('Benefit realization',state.realization),'Each assumption reduces the theoretical benefit independently.')}<div class="grid2">${aiCard('Investment review')}${panel('Evidence to validate',checklist(['Observe current weekly effort','Confirm reduction and review effort','Estimate adoption with real users','Include ongoing operating costs']))}</div></section></div>`}
function roiMethod(){const v=roiValues();modal('Calculation method',`<p>Annual capacity = weekly hours × 52 × effort reduction × adoption × benefit realization.</p><div class="divider"></div><p>${state.hours} × 52 × ${state.reduction}% × ${state.adoption}% × ${state.realization}% = ${v.hours.toFixed(1)} hours.</p><p>Gross value = capacity × loaded hourly rate. Net annual benefit subtracts operating cost. First-year ROI = (net annual benefit − one-time build) ÷ one-time build.</p><div class="actions">${button('Back to model','closeModal()','primary')}</div>`)}
