function contributionBridge(){
  const steps=[['Budget',0,162],['Revenue',162,184],['Delivery',184,168],['OpEx',168,164],['Actual',0,164]];
  const y=v=>154-v*.65;
  return `<figure class="bridge-plot"><svg viewBox="0 0 480 184" role="img" aria-label="Budgeted contribution 162 thousand dollars, plus 22 in revenue, less 16 in delivery costs and 4 in expenses, equals actual contribution of 164 thousand."><line x1="8" x2="472" y1="154" y2="154" stroke="#c7d5df"/>${steps.map(([name,from,to],i)=>{
    const x=18+i*94,change=to-from,total=i===0||i===4;
    return `<rect x="${x}" y="${y(Math.max(from,to))}" width="56" height="${Math.abs(change)*.65}" fill="${total?'#22577a':change>0?'#008375':'#9a4769'}"/>${i<4?`<line x1="${x+56}" x2="${x+94}" y1="${y(to)}" y2="${y(to)}" stroke="#8094a5" stroke-dasharray="3 3"/>`:''}<text x="${x+28}" y="${y(Math.max(from,to))-9}">${total?to:change>0?'+'+change:'−'+Math.abs(change)}</text><text x="${x+28}" y="175">${name}</text>`;
  }).join('')}</svg></figure>`;
}
