function profitFilter(f){state.filter=f;render()}
const supportRequests=[['Morgan Reed','Device will not reconnect','We completed the setup, but the device does not reconnect after a restart. The status indicator is on. What should we check next?'],['Alex Chen','Need help with first setup','We are at the connection step in the setup guide. Can you help us confirm the prerequisites before we continue?'],['Jordan Ellis','Access request is blocked','A new colleague cannot access the workspace. They have an account, but the project is not visible. Who should review the permissions?']];
function supportReply(){return state.reply||`Hi ${supportRequests[state.selected][0].split(' ')[0]},\n\nThanks for the detail. Before we recommend a change, could you confirm the exact status indicator state and the error displayed during reconnection?\n\nThe approved troubleshooting guide starts by checking the connection state and reproducing the issue after a restart. The reviewed prior case followed the same sequence.\n\nPlease share those observations so the team can choose the correct next step. If the documented path does not resolve it, we can prepare an escalation with that context.\n\nAlex`}
SCREENS[18]=()=>`${head(APP.headline,APP.sub,button('Knowledge sources','changeView(2)','','file')+button('Prepare escalation','supportEscalate()','primary','arrow'))}<div class="maildesk"><aside class="panel"><div class="panelhead"><div><h2>Support inbox</h2><p>3 fictional requests</p></div></div>${supportRequests.map((r,i)=>`<button class="mailitem ${state.selected===i?'active':''}" onclick="selectSupport(${i})"><b>${r[0]}</b><p>${r[1]}</p><small>${['High priority · Needs response','Normal · In review','Normal · Escalated'][i]}</small></button>`).join('')}</aside><section class="panel editor"><div class="editorlabel">CASE SUP-${1048+state.selected} / RESPONSE DESK</div><h2>${supportRequests[state.selected][1]}</h2><div class="posthead">${avatar(supportRequests[state.selected][0].split(' ').map(x=>x[0]).join(''))}<div><b>${supportRequests[state.selected][0]}</b><small>Fictional customer email · Today, 8:42 AM</small></div>${tag('Needs review','amber')}</div><p class="small muted" style="font-size:11px;line-height:2">${supportRequests[state.selected][2]}</p><div class="divider"></div><div class="toolbar"><h3>AI-prepared response</h3><span class="draft-status">${state.approved?'Reviewed':'Draft'}</span></div><textarea class="emailbody" id="support-reply" aria-label="Support response draft" oninput="state.reply=this.value;state.approved=false">${esc(supportReply())}</textarea><div class="actions">${button('Inspect prior resolution','supportPrior()','','file')}${button('Refine response','openAI()','','spark')}${button(state.approved?'Reviewed locally':'Mark reviewed','reviewSupport()','primary','check')}</div></section><aside class="stack">${panel('Evidence for the answer',`<span class="upper">APPROVED GUIDANCE</span>${APP.library.map((r,i)=>`<div class="source-card" role="button" tabindex="0" onclick="openSource()" onkeydown="if(event.key==='Enter')openSource()"><h4>${r[0]}</h4><p>${r[1]} · ${r[2]}</p><small>Inspect sample source →</small></div>`).join('')}`)}${aiCard('Missing context','Confirm the indicator state, the exact error, and which troubleshooting steps have already been completed. Do not infer the cause from a similar past case alone.')}</aside></div>`;
function selectSupport(i){state.selected=i;state.reply='';state.approved=false;render()}
function reviewSupport(){state.reply=document.getElementById('support-reply').value;state.approved=true;render();toast('Support draft marked reviewed. No reply was sent.')}
function supportPrior(){modal('Reviewed prior resolution · SUP-0921',`<p>The prior sample case documented the connection state, the exact error, and the steps used to reproduce the issue. A documented restart and connection check resolved that case.</p><div class="divider"></div><p><b>Scope:</b> Similar symptoms do not establish the same cause. Confirm the current request facts before applying the prior resolution.</p><div class="actions">${button('Use as review context','closeModal()','primary')}</div>`)}
function supportEscalate(){modal('Prepare expert escalation',`<div class="field"><label for="escalation-owner">Review owner</label><input id="escalation-owner" value="Support specialist"></div><div class="field"><label for="escalation-question">Open questions</label><textarea id="escalation-question">Confirm the status indicator, the exact error, and the completed troubleshooting steps.</textarea></div><p class="note">The request and source context would travel with the escalation. This demo prepares a local review record only.</p><div class="actions">${button('Save escalation draft','saveEscalation()','primary','check')}</div>`)}
function saveEscalation(){if(!document.getElementById('escalation-owner').value.trim()||!document.getElementById('escalation-question').value.trim()){toast('An owner and an open question are required.');return}closeModal();toast('Escalation draft saved locally. No ticket was sent.')}
SCREENS[19]=()=>`${head('Knowledge search','Search approved context, ask a follow-up, and see what supports the answer.',button('Knowledge library','changeView(1)','','folder'))}<section class="knowledgehero"><span class="eyebrow">CONNECTED COMPANY KNOWLEDGE</span><h1>What do you need to know?</h1><p>Ask across the approved delivery, access, and proposal references.</p><div class="knowledge-search"><input id="knowledge-question" aria-label="Knowledge question" value="${esc(state.knowledgeQuestion||'What needs to be ready before we launch a pilot?')}" onkeydown="if(event.key==='Enter')knowledgeAsk()">${button('Ask the workspace','knowledgeAsk()','primary','spark')}</div></section><div class="layout"><section class="panel"><div class="panelhead"><div><h2>${state.knowledgeQuestion?'Source-aware answer':'Pilot readiness checklist'}</h2><p>${state.knowledgeQuestion?esc(state.knowledgeQuestion):'Prepared from the sample delivery and access references.'}</p></div>${tag(state.knowledgeUnknown?'Source gap':'3 sample references',state.knowledgeUnknown?'amber':'')}</div><div class="panelbody answer">${state.knowledgeUnknown?`<p>I could not find an approved answer to that question in the demonstration references.</p><p>Ask about pilot readiness, project delivery, access approval, or proposal requirements—or send the source gap to a knowledge owner.</p>`:`<p>Before launch, the sample delivery playbook calls for a <b>named business owner, an agreed workflow, approved source access, and representative acceptance cases.</b> ${button('1','knowledgeSource(0)','citation')}</p><p>The access policy requires the intended users and their roles to be reviewed before connecting the source. The application should only use the information each role is allowed to access. ${button('2','knowledgeSource(1)','citation')}</p><p>Record the acceptance decision and the handoff owner. Use the first pilot to review real usage and outcomes before expanding the workflow. ${button('3','knowledgeSource(2)','citation')}</p>`}<div class="divider"></div><div class="actions">${button('What needs human review?','knowledgeFollowup()','','spark')}${button('Inspect source context','openSource()','','file')}${button('Save answer','saveKnowledge()','primary','check')}</div><p class="note" style="margin-top:19px">Fictional source material and predefined response logic. An unsupported question produces a visible source gap.</p></div></section><aside class="stack">${panel('Sources behind the answer',APP.rows.map((r,i)=>`<div class="source-card" role="button" tabindex="0" onclick="knowledgeSource(${i})" onkeydown="if(event.key==='Enter')knowledgeSource(${i})"><h4>${i+1}. ${r[0]}</h4><p>${r[1]} · ${r[2]}</p><small>${r[4]} · Reviewed ${r[3]}</small></div>`).join(''))}${panel('Knowledge coverage',bar('Reviewed references',100,'3 / 3')+bar('Open review items',67,'2 open')+`<p class="note">Counts describe this fictional source collection.</p>`)}</aside></div>`;
function knowledgeAsk(){const q=document.getElementById('knowledge-question').value.trim();if(!q)return;state.knowledgeQuestion=q;state.knowledgeUnknown=!/pilot|launch|ready|readiness|delivery|access|approval|proposal|owner|review/i.test(q);render()}
function knowledgeSource(i){modal(APP.rows[i][0],`<span class="responsibility">FICTIONAL APPROVED REFERENCE</span><div class="divider"></div><p>${['The delivery owner must confirm the business objective, source access, acceptance cases, and accountable handoff before a pilot is released.','Access should be reviewed by the source owner and appropriate technical contact. Define intended roles, information scope, and approval before connecting a source.','Proposals should keep delivery assumptions, review points, acceptance criteria, and client responsibilities explicit. Confirm unresolved details before submitting.'][i]}</p><div class="divider"></div><p class="note">Sample excerpt for this designed example. Production answers would cite your real approved source and version.</p><div class="actions">${button('Return to answer','closeModal()','primary')}</div>`)}
function knowledgeFollowup(){state.aiMessages=[{q:'What needs human review?',a:'The business owner confirms the outcome and acceptance. The source owner and IT review access. Representative users validate that the workflow is useful. A subject matter expert reviews domain-specific answers where the consequences require it.'}];drawAI()}
function saveKnowledge(){download('sample-pilot-readiness.txt',state.knowledgeUnknown?'No approved source answer found.':APP.ai);toast('Sample answer downloaded.')}
