if (readOnlyPreview) {
  document.body.classList.add('readonly-preview');
  const workspace = document.getElementById('app');
  for (const type of ['click','submit','beforeinput','dragstart','keydown']) {
    workspace.addEventListener(type,event=>{
      if(event.target.closest('.appnav,[data-browse]') || (type==='keydown' && !['Enter',' '].includes(event.key))) return;
      event.preventDefault();
      event.stopImmediatePropagation();
    },true);
  }
}
